/* ---- Solution ---- */
.board {
  display: flex;
  justify-content: center;
  padding-top: 56px;
  background-color: #c8a27a;
  background-image: radial-gradient(rgb(0 0 0 / 0.08) 1px, transparent 1px);
  background-size: 10px 10px;
}

.polaroid {
  position: relative;
  width: 170px;
  padding: 12px 12px 14px;
  background-color: #ffffff;
  box-shadow: 0 8px 16px rgb(0 0 0 / 0.25);
}

.polaroid + .polaroid {
  margin-left: -30px;
}

.polaroid::before {
  content: "";
  position: absolute;
  top: -12px;
  left: 50%;
  width: 70px;
  height: 24px;
  background-color: rgb(254 243 199 / 0.75);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.15);
  transform: translateX(-50%) rotate(-4deg);
}

.p1 {
  transform: rotate(-6deg);
}

.p2 {
  z-index: 1;
  transform: rotate(3deg) translateY(-16px);
}

.p3 {
  transform: rotate(8deg);
}

.photo {
  height: 150px;
}

.caption {
  margin-top: 10px;
  text-align: center;
}
